function inspectFocus(){for(const card of $$('.game')){const series=card.querySelector('.season-series')?.textContent?.match(/客隊 (\d+)–(\d+) 主隊/);if(series){const away=teamIdFromLogo(card.querySelector('.team-mark img')),home=teamIdFromLogo(card.querySelectorAll('.team-mark img')[1]),a=Number(series[1]),h=Number(series[2]),total=a+h;if(total>5){if(a/total>=.8)addFocus(`series-${away}-${home}`,'對戰優勢',names[away]||short[away],`本季對 ${names[home]||short[home]} ${a}-${h}（${Math.round(a/total*100)}%）`,'positive',away);if(h/total>=.8)addFocus(`series-${home}-${away}`,'對戰優勢',names[home]||short[home],`本季對 ${names[away]||short[away]} ${h}-${a}（${Math.round(h/total*100)}%）`,'positive',home)}}for(const pitcher of card.querySelectorAll('.pitcher')){const stats=[...pitcher.querySelectorAll('.stat-value')].map(x=>x.textContent.trim()),m=stats[0]?.match(/(\d+)\s*-\s*(\d+)/),era=Number(stats[1]);if(!m||!Number.isFinite(era))continue;const wins=Number(m[1]),losses=Number(m[2]),total=wins+losses,winPct=total?wins/total:0,diff=Math.abs(wins-losses),name=pitcher.querySelector('.pitcher-name')?.textContent.trim()||'先發投手',teamId=teamIdFromLogo(pitcher.closest('.team')?.querySelector('.team-mark img')),playerId=pitcher.querySelector('.headshot')?.src.match(/people\/(\d+)\//)?.[1],high=total>5&&winPct>.8&&era<4,low=total>5&&winPct<.2&&era>5,strong=high||(diff>=5&&wins>losses),weak=low||(diff>=5&&losses>wins);if(!strong&&!weak)continue;const type=strong?'強勢先發':'低迷先發',teamName=names[teamId]||short[teamId]||'球隊';addFocus(`pitcher-${name}`,type,name,`${teamName}・勝敗 ${wins}-${losses}・勝率 ${Math.round(winPct*100)}%・ERA ${era.toFixed(2)}`,strong?'positive':'negative',teamId,playerId)}}}
let gameFilter='all';
function setupFilters(){if($('#game-filters'))return;const filters=document.createElement('div');filters.id='game-filters';filters.className='game-filters';filters.setAttribute('aria-label','篩選賽程');filters.innerHTML='<span>顯示比賽</span><button class="filter selected" data-filter="all" aria-pressed="true">全部</button><button class="filter" data-filter="Preview" aria-pressed="false">未開賽</button><button class="filter" data-filter="Live" aria-pressed="false">進行中</button><button class="filter" data-filter="Final" aria-pressed="false">已結束</button>';$('#schedule-panel .toolbar').after(filters);filters.addEventListener('click',e=>{const button=e.target.closest('[data-filter]');if(!button)return;gameFilter=button.dataset.filter;$$('.filter').forEach(x=>{const selected=x===button;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))});applyGameFilter()})}
function gameState(card){const state=card.querySelector('.game-top>span:last-child')?.textContent||'';return state.includes('進行中')?'Live':state.includes('已結束')?'Final':'Preview'}
function applyGameFilter(){$$('.game').forEach(card=>{const state=gameState(card);card.dataset.gameState=state;card.hidden=gameFilter!=='all'&&gameFilter!==state})}
if(typeof document!=='undefined'){setupFilters();const games=$('#games');new MutationObserver(records=>{if(records.some(r=>r.target===games)){focusRun=sequence;focusItems=[];renderFocus();loadSeasonSeries();loadLiveScores()}applyGameFilter();inspectFocus()}).observe(games,{childList:true,subtree:true});}
